88	function formatLog(level: LogLevel, message: string, meta: LogMeta = undefined) {
89	  const timestamp = new Date().toISOString();
90	  if (!meta || Object.keys(meta).length === 0) {
91	    return `[${timestamp}] ${level.toUpperCase()} ${message}`;
92	  }
93	  let serializedMeta = '';
94	  try {
95	    serializedMeta = JSON.stringify(meta);
96	  } catch (error) {
97	    serializedMeta = String(meta);
98	  }
99	  return `[${timestamp}] ${level.toUpperCase()} ${message} ${serializedMeta}`;
100	}
