131	function exportDocsAsPdf() {
132	  const existing = DOC_FILENAMES.filter((file) => fs.existsSync(file));
133	  if (!existing.length) {
134	    log.warn('No documentation files to export.');
135	    return;
136	  }
137	  try {
138	    execSync(`npx markdown-pdf ${existing.join(' ')}`, { stdio: 'inherit' });
139	    log.success('PDF export complete.');
140	  } catch (error) {
141	    log.error('Failed to export documentation as PDF.', {
142	      error: error instanceof Error ? error.message : String(error)
143	    });
144	  }
145	}
