197	async function promptForApiKey(scopeGlobal?: boolean) {
198	  const answers = await inquirer.prompt<{ apiKey: string }>([
199	    {
200	      type: 'password',
201	      name: 'apiKey',
202	      message: `Enter your OpenAI API key (${scopeGlobal ? 'global' : 'local'} storage):`,
203	      mask: '*',
204	      validate: (value) => Boolean(value?.trim()) || 'API key is required.'
205	    }
206	  ]);
207	  await configureApiKeyIfProvided(answers.apiKey, scopeGlobal);
208	  return answers.apiKey;
209	}
